{"witnessCode": "import assert from 'node:assert/strict';
import x from '../index.js';

assert.throws(
  () => {
    x('foo.bar://example.com/path/');
  },
  (err) => {
    return err instanceof TypeError && err.code === 'ERR_INVALID_URL';
  },
  'Expected ERR_INVALID_URL for URLs with dot-containing custom protocols'
);
"}
